//! Cross-crate constant values through the original native evaluator/checker.
use super::*;
use crate::ty::TyIntern;
const FIRST:&str="#![no_std]\npub const ANSWER:i64={let x=6;x*7};\npub fn value()->i64{ANSWER}\n";
fn record(root:&std::path::Path,label:&str,o:&std::process::Output){put(&root.join(format!("{label}.stdout")),&o.stdout);put(&root.join(format!("{label}.stderr")),&o.stderr);put(&root.join(format!("{label}.status")),o.status.to_string().as_bytes());}
pub(super) fn first(root:&std::path::Path,generation:&native_crate::Generation,backend:&native_crate::Backend){
    let source=root.join("original.rs");put(&source,FIRST.as_bytes());let image=root.join("original.lustr-native");
    let(code,message)=native_object::run_artifact(&args(&source,&image,"const_first"),generation,backend);put(&root.join("original.native.log"),message.as_bytes());put(&root.join("original.native.status"),code.to_string().as_bytes());assert_eq!(code,1,"{message}");assert!(!image.exists());assert!(message.contains("exported non-function records"),"{message}");
    let o=std::process::Command::new("/core/bin/rustc").arg(&source).args(["--edition=2024","--crate-name","same","--crate-type=rlib","--target=x86_64-unknown-linux-gnu","-Cpanic=abort","-Copt-level=0","-Cdebuginfo=0","-Coverflow-checks=off","-Cdebug-assertions=off"]).arg("-o").arg(root.join("liboriginal.rlib")).output().unwrap();record(root,"original.oracle-build",&o);assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));
    println!("original public constant: native refusal/no image/no apps; separate explicit SDK oracle rlib pass");
}
const VALUES:&str="#![no_std]\nconst HIDDEN:i64=11;pub const EXPORTED:i64=HIDDEN;pub use EXPORTED as AGAIN;\npub const FLAG:bool=true;pub const LETTER:char='λ';pub const BIG:u128=340282366920938463463374607431768211455;pub const LOW:i128=-170141183460469231731687303715884105728;pub const FLOAT:f64=1.5;pub const PAIR:(i64,bool)=(7,true);pub const ARRAY:[i64;3]=[2,4,8];pub const REPEAT:[i64;5]=[3;5];pub const ZERO:[u8;0]=[];pub const UNIT:()=();\npub struct Packet{pub value:i64,pub ready:bool}pub const PACKET:Packet=Packet{value:19,ready:true};pub enum Mode{Off,Value(i64),Record{value:i64}}pub const MODE:Mode=Mode::Value(23);pub const OFF:Mode=Mode::Off;pub const RECORD:Mode=Mode::Record{value:29};\npub fn read(p:Packet)->i64{if p.ready{p.value}else{0}}pub fn mode(m:Mode)->i64{match m{Mode::Off=>0,Mode::Value(v)=>v,Mode::Record{value}=>value}}\n";
pub(super) fn run(root:&std::path::Path,generation:&native_crate::Generation,backend:&native_crate::Backend){
    let mut images=Vec::new();for(label,text,metadata)in[("original",FIRST,"const_first"),("other","#![no_std]\npub const ANSWER:i64=9;pub fn value()->i64{ANSWER}\n","const_other"),("values",VALUES,"const_values"),("only","#![no_std]\npub const NUMBER:i64=31;\n","const_only"),("privateconst","#![no_std]\nconst HIDDEN:&str=\"private\";pub fn value()->i64{37}\n","private_const")]{
        let source=root.join(format!("{label}.rs"));put(&source,text.as_bytes());let image=root.join(format!("{label}.lustr-native"));let(code,message)=native_object::run_artifact(&args(&source,&image,metadata),generation,backend);put(&root.join(format!("{label}.native.log")),message.as_bytes());put(&root.join(format!("{label}.native.status")),code.to_string().as_bytes());assert_eq!(code,0,"{label}: {message}");let b=std::fs::read(&image).unwrap();let a=native_crate::Artifact::decode(&b,generation).unwrap();assert_eq!(a.encode().unwrap(),b);images.push((label.into(),a));
        let o=std::process::Command::new("/core/bin/rustc").arg(&source).args(["--edition=2024","--crate-name","same","--crate-type=rlib","--target=x86_64-unknown-linux-gnu","-Cpanic=abort","-Copt-level=0","-Cdebuginfo=0","-Coverflow-checks=off","-Cdebug-assertions=off"]).arg(format!("-Cmetadata={metadata}")).arg("-o").arg(root.join(format!("lib{label}.rlib"))).output().unwrap();record(root,&format!("producer-{label}.oracle-build"),&o);assert!(o.status.success(),"{label}: {}",String::from_utf8_lossy(&o.stderr));
    }
    let ids=def::CrateIds{local:def::LOCAL_CRATE,stable:def::stable_crate_hash("const-consumer","bin","consumer",false)};let store=native_crate::CrateStore::new(images,ids).unwrap();
    for(label,text,valid,diagnosis)in[
        ("direct","use original::{ANSWER,value};use other::ANSWER as OTHER;use only::NUMBER;use privateconst::value as PRIVATE_VALUE;const LOCAL:i64=ANSWER+1;fn main(){assert!(ANSWER==42);assert!(value()==42);assert!(OTHER==9);assert!(LOCAL==43);assert!(NUMBER==31);assert!(PRIVATE_VALUE()==37);}",true,""),
        ("values","use values::*;fn main(){assert!(EXPORTED==11);assert!(AGAIN==11);assert!(FLAG);assert!(LETTER=='λ');assert!(BIG==340282366920938463463374607431768211455u128);assert!(LOW==(-170141183460469231731687303715884105728i128));assert!(FLOAT==1.5);assert!(PAIR.0==7);assert!(PAIR.1);assert!(ARRAY[2]==8);assert!(REPEAT[4]==3);let z:[u8;0]=ZERO;let u:()=UNIT;assert!(read(PACKET)==19);assert!(mode(MODE)==23);assert!(mode(OFF)==0);assert!(mode(RECORD)==29);assert!(read(PACKET)==19);}",true,""),
        ("patterns","use original::ANSWER;use values::{FLAG,LETTER};fn main(){let x=42;match x{ANSWER=>{},_=>panic!(\"constant pattern\")};match true{FLAG=>{},_=>panic!(\"bool pattern\")};match 'λ'{LETTER=>{},_=>panic!(\"char pattern\")};}",true,""),
        ("const-created-import-call","use original::value;const fn make()->fn()->i64{||value()}fn main(){assert!(make()()==42);}",true,""),
        ("const-inside-import-closure","use original::value;const fn make()->fn()->i64{||const{if false{value()}else{42}}}fn main(){}",false,"L0631"),
        ("private","use values::HIDDEN;fn main(){let x=HIDDEN;}",false,"private"),
        ("type","use original::ANSWER;fn main(){let x:bool=ANSWER;}",false,"L0110"),
        ("assign","use original::ANSWER;fn main(){ANSWER=0;}",false,""),
        ("call","use original::ANSWER;fn main(){ANSWER();}",false,""),
    ]{
        let source=root.join(format!("{label}-consumer.rs"));put(&source,text.as_bytes());let mut req=input(root,text,ids);req.env=resolve::cfg::CfgEnv::new("x86_64-unknown-linux-gnu",&[],false,protocol::ProfileFlags{panic_abort:true,overflow_checks:false,debug_assertions:false});let out=root.join(format!("{label}-native"));let result=store.executable(&req,generation,backend,&out);put(&root.join(format!("{label}.native.result")),format!("{result:?}").as_bytes());if valid{result.unwrap_or_else(|e|panic!("{label}: {e}"));}else{let e=result.err().expect("invalid constant consumer emitted output; NEVER execute");assert!(!out.join("app").exists());assert!(e.contains(diagnosis),"{label}: {e}");}
        let mut c=std::process::Command::new("/core/bin/rustc");c.arg(&source).args(["--edition=2024","--crate-name","consumer","--target=x86_64-unknown-linux-gnu","-Cpanic=abort","-Copt-level=0","-Cdebuginfo=0","-Coverflow-checks=off","-Cdebug-assertions=off"]);for label in["original","other","values","only","privateconst"]{c.arg("--extern").arg(format!("{label}={}",root.join(format!("lib{label}.rlib")).display()));}let app=root.join(format!("{label}-oracle"));let o=c.arg("-o").arg(&app).output().unwrap();record(root,&format!("{label}.oracle-build"),&o);assert_eq!(o.status.success(),valid,"{label}: {}",String::from_utf8_lossy(&o.stderr));if valid{let n=std::process::Command::new(out.join("app")).output().unwrap();record(root,&format!("{label}.native-app"),&n);assert!(n.status.success());let o=std::process::Command::new(app).output().unwrap();record(root,&format!("{label}.oracle-app"),&o);assert!(o.status.success());assert_eq!(n.stdout,o.stdout);assert_eq!(n.stderr,o.stderr);}
    }
    for(label,text,want)in[("division","#![no_std]\npub const INVALID:i64=1/0;pub fn value()->i64{0}\n","zero"),("move","#![no_std]\npub struct Packet{pub v:i64}pub const INVALID:(Packet,Packet)={let p=Packet{v:3};(p,p)};pub fn value()->i64{0}\n","L0301"),("dead-nonconst","#![no_std]\npub fn value()->bool{true}pub const INVALID:bool=false&&value();\n","L0631"),("dead-or","#![no_std]\npub fn value()->bool{true}pub const INVALID:bool=true||value();\n","L0631"),("wrapped","#![no_std]\npub fn value()->bool{true}pub const INVALID:bool=const{false&&value()};\n","L0631"),("nested-wrapped","#![no_std]\npub fn value()->bool{true}pub const INVALID:bool=const{const{true||value()}};\n","L0631"),("dead-if","#![no_std]\npub fn value()->i64{7}pub const INVALID:i64=if false{value()}else{3};\n","L0631"),("dead-type","#![no_std]\npub const INVALID:i64=if false{true}else{3};pub fn value()->i64{0}\n","L0110")]{let source=root.join(format!("invalid-{label}.rs"));put(&source,text.as_bytes());let image=root.join(format!("invalid-{label}.lustr-native"));let(code,message)=native_object::run_artifact(&args(&source,&image,&label.replace('-',"_")),generation,backend);put(&root.join(format!("invalid-{label}.native.log")),message.as_bytes());assert_eq!(code,1);assert!(message.contains(want),"{label}: {message}");assert!(!image.exists());let o=std::process::Command::new("/core/bin/rustc").arg(source).args(["--edition=2024","--crate-name","invalid","--crate-type=rlib"]).arg("-o").arg(root.join(format!("invalid-{label}.rlib"))).output().unwrap();record(root,&format!("invalid-{label}.oracle-build"),&o);assert!(!o.status.success());}
    malformed(root,generation);expanded_malformed(root,generation);late_abi(root,generation,backend,ids);remap(root,generation,ids);
    println!("native constant image gate PASS; generic const bodies/references/core/no_std runtime/full Cargo/SAME complete-work remain OPEN");
}
fn footer(b:&[u8])->(usize,usize){fn n(b:&[u8],at:usize)->usize{u32::from_le_bytes(b[at..at+4].try_into().unwrap())as usize}let mut at=b"LUSTR-NATIVE-CRATE\0\x09".len()+64;for _ in 0..4{at+=4+n(b,at);}at+=8+32+2;let count=n(b,at);at+=4;for _ in 0..count{at+=16;at+=4+n(b,at);at+=1;let count=n(b,at);at+=4+4*count+4;at+=4+n(b,at);}let graph=at+4;for _ in 0..5{at+=4+n(b,at);}assert_eq!(at+4+n(b,at),b.len());(at,graph)}
fn malformed(root:&std::path::Path,generation:&native_crate::Generation){let b=std::fs::read(root.join("original.lustr-native")).unwrap();let p=&b[..b.len()-32];let(at,_)=footer(p);let record=at+8;let name=record+16;let ty=name+4+6;let qual=ty+4;let val=qual+2;assert_eq!(p[val],3);
    let reject=|label:&str,mut b:Vec<u8>,want:&str|{b.extend_from_slice(&native_crate::digest(&b).unwrap());put(&root.join(format!("malformed-{label}.lustr-native")),&b);let e=native_crate::Artifact::decode(&b,generation).err().expect("invalid constant image accepted");put(&root.join(format!("malformed-{label}.log")),e.as_bytes());assert!(e.contains(want),"{label}: {e}");};
    for(label,pos,want)in[("identity",record,"definition identity"),("name",name+4,"definition identity"),("type",ty,"type index"),("qualifier",qual,"qualifiers unsupported"),("value-tag",val,"value tag")]{let mut b=p.to_vec();b[pos]=if label=="type"||label=="value-tag"{255}else{b[pos]^1};reject(label,b,want);}
    let mut b=p.to_vec();b[val+1..val+17].copy_from_slice(&i128::MAX.to_le_bytes());reject("integer-range",b,"range/type");
    let mut b=p[..at+4].to_vec();b.extend_from_slice(&0u32.to_le_bytes());b[at..at+4].copy_from_slice(&4u32.to_le_bytes());reject("missing-value",b,"definition/value");
    let mut b=p.to_vec();let extra=p[record..].to_vec();b.extend_from_slice(&extra);b[at+4..at+8].copy_from_slice(&2u32.to_le_bytes());b[at..at+4].copy_from_slice(&((p.len()-at-4+extra.len())as u32).to_le_bytes());reject("duplicate-value",b,"definition identity");
    let mut b=p.to_vec();b[b"LUSTR-NATIVE-CRATE\0".len()]=8;reject("old-format8",b,"format generation");
}
fn remap(root:&std::path::Path,generation:&native_crate::Generation,ids:def::CrateIds){
    let a=native_crate::Artifact::decode(&std::fs::read(root.join("original.lustr-native")).unwrap(),generation).unwrap();let stable=a.functions()[0].id.krate;let store=native_crate::CrateStore::new(vec![("original".into(),a)],ids).unwrap();let i=std::sync::Arc::new(intern::Interner::default());for n in 0..200{i.intern(&format!("const_noise_{n}"));}let k=std::sync::Arc::new(intern::Known::new(&i));let req=input(root,"const LOCAL:i64=17;fn main(){}",ids);let resolved=resolve_ok(&store,&req,&i,&k);let tables=std::sync::Arc::new(resolved.tables);let mut order=check::collect::DefOrder::default();let mut p=check::collect::collect_with_order_resolved(std::sync::Arc::new(resolved.ast),i,k,ids,false,&mut order,Some(tables.clone())).unwrap_or_else(|e|panic!("remap collect {}",e.len()));let fns=p.fns.len();let local=p.consts.len();assert_eq!(local,1);store.install_signatures(&mut p).unwrap();assert_eq!(p.fns.len(),fns);assert_eq!(p.consts.len(),local+1);assert_eq!(p.consts[0].value,ty::consteval::ConstValue::Int(17));let d=def::DefId{krate:def::CrateId(1),hash:def::item_hash(stable,&[],def::DefKind::Const,"ANSWER",0)};let index=p.const_by_def(d).unwrap();assert_eq!(index as usize,local);assert_eq!(p.const_names[&tables.def_info[&d].flat],index);assert_eq!(p.consts[index as usize].value,ty::consteval::ConstValue::Int(42));assert_eq!(p.tys.kind(p.consts[index as usize].ty),ty::TyKind::Int(ty::IntTy::I64));put(&root.join("remap-install-only.txt"),b"Full foreign const identity/value/type/name remaps after fresh interner and existing local constant; no extra FnInfo. INSTALL ONLY, not execution from this Program.\n");
}
fn expanded_malformed(root:&std::path::Path,generation:&native_crate::Generation){
    // Valid checksums exercise the value schema, not corruption detection.
    let bytes=std::fs::read(root.join("values.lustr-native")).unwrap();let p=&bytes[..bytes.len()-32];let(at,_)=footer(p);let start=at+4;let mut pos=start+4;let count=u32::from_le_bytes(p[start..start+4].try_into().unwrap());let mut fields=std::collections::BTreeMap::new();
    fn n(b:&[u8],at:usize)->usize{u32::from_le_bytes(b[at..at+4].try_into().unwrap())as usize}
    fn skip(b:&[u8],at:&mut usize){let tag=b[*at];*at+=1;match tag{0=>{},1=>*at+=1,2=>*at+=4,3=>*at+=16,4=>*at+=9,5|6=>{if tag==6{*at+=4;}let count=n(b,*at);*at+=4;for _ in 0..count{skip(b,at);}},7=>{*at+=8;skip(b,at);},_=>panic!("fixture value tag")}}
    for _ in 0..count{pos+=16;let len=n(p,pos);pos+=4;let name=std::str::from_utf8(&p[pos..pos+len]).unwrap().to_owned();pos+=len+4+2;fields.insert(name,pos);skip(p,&mut pos);}assert_eq!(pos,p.len());
    let reject=|label:&str,mut b:Vec<u8>,want:&str|{b.extend_from_slice(&native_crate::digest(&b).unwrap());put(&root.join(format!("malformed-{label}.lustr-native")),&b);let e=native_crate::Artifact::decode(&b,generation).err().expect("malformed typed value accepted");put(&root.join(format!("malformed-{label}.log")),e.as_bytes());assert!(e.contains(want),"{label}: {e}");};
    let v=fields["FLAG"];let mut b=p.to_vec();b[v+1]=2;reject("boolean",b,"boolean");
    let v=fields["LETTER"];let mut b=p.to_vec();b[v+1..v+5].copy_from_slice(&0xd800u32.to_le_bytes());reject("unicode-scalar",b,"char");
    let v=fields["FLOAT"];let mut b=p.to_vec();assert_eq!(b[v],4);b[v+1]=0;reject("float-width",b,"shape mismatch");
    let v=fields["MODE"];let mut b=p.to_vec();assert_eq!(b[v],6);b[v+1..v+5].copy_from_slice(&u32::MAX.to_le_bytes());reject("enum-index",b,"variant index");
    let v=fields["PAIR"];let mut b=p.to_vec();assert_eq!(b[v],5);b[v+1..v+5].copy_from_slice(&u32::MAX.to_le_bytes());reject("aggregate-count",b,"exceeds bound");
    let v=fields["REPEAT"];let mut b=p.to_vec();assert_eq!(b[v],7);b[v+1..v+9].copy_from_slice(&6u64.to_le_bytes());reject("repeat-length",b,"shape mismatch");
    let mut b=p.to_vec();b[v+1..v+9].copy_from_slice(&u64::MAX.to_le_bytes());reject("repeat-overflow",b,"shape mismatch");
    // A long but checksum-valid recursive value stops at the decoder's bound.
    let mut deep=Vec::new();for _ in 0..130{deep.push(5);deep.extend_from_slice(&1u32.to_le_bytes());}deep.push(0);let mut end=v;skip(p,&mut end);let mut b=p[..v].to_vec();b.extend_from_slice(&deep);b.extend_from_slice(&p[end..]);let size=(b.len()-at-4)as u32;b[at..at+4].copy_from_slice(&size.to_le_bytes());reject("value-depth",b,"depth/work bound");
}
fn late_abi(root:&std::path::Path,generation:&native_crate::Generation,backend:&native_crate::Backend,ids:def::CrateIds){
    let left=std::fs::read(root.join("original.lustr-native")).unwrap();let right=std::fs::read(root.join("other.lustr-native")).unwrap();let a=native_crate::Artifact::decode(&left,generation).unwrap();let b=native_crate::Artifact::decode(&right,generation).unwrap();let(good,target)=if a.functions()[0].id.krate<b.functions()[0].id.krate{(a,right)}else{(b,left)};let p=&target[..target.len()-32];let(_,graph)=footer(p);assert_eq!(p[graph+4],7); // scalar i64
    let mut changed=p.to_vec();let abi=graph+4+1+16+4+1+3;changed[abi+16]^=1;changed.extend_from_slice(&native_crate::digest(&changed).unwrap());put(&root.join("malformed-later-const-abi.lustr-native"),&changed);let bad=native_crate::Artifact::decode(&changed,generation).unwrap();assert!(good.functions()[0].id.krate<bad.functions()[0].id.krate);
    let store=native_crate::CrateStore::new(vec![("good".into(),good),("bad".into(),bad)],ids).unwrap();let i=std::sync::Arc::new(intern::Interner::default());let k=std::sync::Arc::new(intern::Known::new(&i));let req=input(root,"const FAIL:i64=1/0;fn main(){}",ids);let resolved=resolve_ok(&store,&req,&i,&k);let tables=std::sync::Arc::new(resolved.tables);let foreign:Vec<_>=tables.def_info.keys().copied().filter(|d|d.krate!=def::LOCAL_CRATE).collect();let mut order=check::collect::DefOrder::default();let mut called=false;let mut install=|p:&mut check::collect::Program|{called=true;let e=store.install_signatures(p).unwrap_err();assert!(e.contains("C ABI mismatch"));assert!(p.consts.is_empty()&&p.const_defs.is_empty()&&p.const_names.is_empty());assert!(p.regions.native_fns.is_empty());for d in &foreign{assert!(p.defs.get(*d).is_none());}Err(vec![diag::Diag::new("L0508",diag::Span::default(),e,"Expected refusal before any constant publication")])};let result=check::collect::collect_with_definitions(std::sync::Arc::new(resolved.ast),i,k,ids,false,&mut order,Some(tables),&mut install);assert!(called);let mut errors=result.err().expect("late malformed ABI admitted");let text=diag::render(&mut errors,&resolved.map,&resolved.all_text,false,20);assert!(!text.contains("division by zero"));put(&root.join("later-const-abi-before-publication.log"),text.as_bytes());
    let mut req=input(root,"const FAIL:i64=1/0;fn main(){}",ids);req.env=resolve::cfg::CfgEnv::new("x86_64-unknown-linux-gnu",&[],false,protocol::ProfileFlags{panic_abort:true,overflow_checks:false,debug_assertions:false});let out=root.join("later-const-abi-native");let e=store.executable(&req,generation,backend,&out).unwrap_err();assert!(e.contains("C ABI mismatch"));assert!(!out.exists());
}
